from itertools import combinations


def assess(attrs):
    fields = ['price', 'admin', 'group_cap', 'global_claw']
    fields += ['loss_' + str(i) for i in range(6)]
    fields += ['claw_' + str(g) for g in range(3)]
    for key in fields:
        value = attrs.get(key)
        if type(value) is not int or value < 0:
            return {'feasible': False, 'utility': None}

    price = attrs['price']
    if price > 1200000:
        return {'feasible': False, 'utility': None}

    losses = [attrs['loss_' + str(i)] for i in range(6)]
    claws = [attrs['claw_' + str(g)] for g in range(3)]
    worst = 0  # The empty event has zero assessment.
    for count in range(1, 5):
        for cancelled in combinations(range(6), count):
            personal = sum(losses[i] for i in cancelled)
            group_total = sum(
                claws[g] for g in range(3)
                if (2 * g in cancelled) != (2 * g + 1 in cancelled)
            )
            amount = personal + min(group_total, attrs['group_cap'])
            if count >= 2 and 0 not in cancelled:
                amount += attrs['global_claw']
            amount += attrs['admin']
            if amount > 200000:
                return {'feasible': False, 'utility': None}
            worst = max(worst, amount)

    return {'feasible': True, 'utility': str(2000000 - price - worst)}
